const TOOL_NAME = 'text_transform';
const MODES = new Set(['uppercase', 'lowercase', 'slug']);
const ALLOWED_KEYS = new Set(['text', 'mode', 'trim']);

function slugify(text, trim) {
  let s = text;
  if (trim) s = s.trim();
  s = s.toLowerCase();
  s = s.replace(/[^a-z0-9]+/g, '-');
  s = s.replace(/^-+|-+$/g, '');
  return s;
}

export async function listTools() {
  return [
    {
      name: TOOL_NAME,
      description: 'Transform a text string using a chosen mode.',
      inputSchema: {
        type: 'object',
        properties: {
          text: {
            type: 'string',
            description: 'The text to transform.',
          },
          mode: {
            type: 'string',
            enum: ['uppercase', 'lowercase', 'slug'],
            description: 'Transformation mode to apply.',
          },
          trim: {
            type: 'boolean',
            default: true,
            description: 'Whether to trim the input before transforming (default true).',
          },
        },
        required: ['text', 'mode'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('arguments must be an object');
  }

  for (const key of Object.keys(args)) {
    if (!ALLOWED_KEYS.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  const { text, mode } = args;
  if (text === undefined) throw new Error('Missing required argument: text');
  if (mode === undefined) throw new Error('Missing required argument: mode');
  if (typeof text !== 'string') throw new Error('text must be a string');
  if (typeof mode !== 'string') throw new Error('mode must be a string');
  if (!MODES.has(mode)) throw new Error(`Invalid mode: ${mode}`);

  let trim = true;
  if (args.trim !== undefined) {
    if (typeof args.trim !== 'boolean') throw new Error('trim must be a boolean');
    trim = args.trim;
  }

  let result;
  switch (mode) {
    case 'uppercase':
      result = trim ? text.trim().toUpperCase() : text.toUpperCase();
      break;
    case 'lowercase':
      result = trim ? text.trim().toLowerCase() : text.toLowerCase();
      break;
    case 'slug':
      result = slugify(text, trim);
      break;
  }

  return {
    content: [{ type: 'text', text: result }],
  };
}

